window.ATLAS.addDetails("matter.edges",{"edges":{
"activation-energy:dynamic-equilibrium":{"type":"connection","label":{"zh":"催化剂同时降低两个方向的山","en":"A catalyst lowers the hill in both directions"},"reason":{"zh":"活化能页说明催化剂降低能垒、逆反应同理；正、逆两个速率按同一倍数提高，所以平衡更快到达，平衡时的组成却不变。","en":"The activation-energy lesson shows a catalyst lowers the barrier for the reverse reaction as well; both rates rise by the same factor, so equilibrium arrives sooner with the same composition."},"source":"../chemistry/reactions/chemical-equilibrium/#step4"},
"atomic-structure:conservation-of-mass":{"type":"foundation","label":{"zh":"化学反应不改变原子核","en":"Chemical reactions leave nuclei alone"},"reason":{"zh":"化学反应只是把原子重新连接，核里的质子数不变，原子不会变成别的元素；所以每种元素的原子在反应前后一个不多、一个不少。","en":"A chemical reaction only reconnects atoms; the proton count in each nucleus is unchanged, so no atom turns into another element and every element has exactly as many atoms after the reaction as before."},"source":"../chemistry/reactions/mass-conservation/#step1"},
"atomic-structure:electron-shells":{"type":"foundation","label":{"zh":"质子数定下电子数","en":"The proton count fixes the electron count"},"reason":{"zh":"中性原子的电子数等于质子数，所以先由质子数知道一共有几个电子，才能一层层排出最外层还剩几个。","en":"A neutral atom has as many electrons as protons, so the proton count says how many electrons there are before they can be filled shell by shell to find what is left on the outside."},"source":"../chemistry/matter/atomic-structure/#step2"},
"buffer-solution:titration-curves":{"type":"connection","label":{"zh":"缓冲区就是滴定曲线的平台","en":"The buffer region is the flat stretch of a titration curve"},"reason":{"zh":"弱酸被强碱滴定时，半等当点附近 HA 与 A⁻ 各占一半、pH = pKa，曲线最平——这段平台正是缓冲作用；库存耗尽，曲线就陡起来。","en":"When a weak acid is titrated with a strong base, near half-equivalence HA and A⁻ are equal, pH = pKa and the curve is flattest — that plateau is buffering at work; once the reserve runs out, the curve turns steep."},"source":"../chemistry/solutions/buffer-capacity/#step2"},
"cell-structure:molecules-atoms":{"type":"foundation","label":{"zh":"细胞是分子搭成的车间","en":"Cells are workshops built from molecules"},"reason":{"zh":"从叶子逐级放大到细胞，是同一条尺度链的下一级：细胞比分子大得多，里面的工位全由分子搭成。","en":"Zooming from a leaf down to a cell is the next level of the same scale chain: cells are far larger than molecules, and every workstation inside is built from them."},"source":"../biology/cells/cell-structure/#step0"},
"century-egg-alkali:fermented-food-family":{"type":"foundation","label":{"zh":"碱和酶并排比","en":"Alkali beside enzymes"},"reason":{"zh":"第 7 章把第 6 章的碱法和前面几章的酶法并排，回答两者是不是同一个原理。","en":"Chapter 7 sets chapter 6’s alkali route beside the enzyme route of the earlier chapters to answer whether the two are one principle."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch7"},
"collision-theory:activation-energy":{"type":"foundation","label":{"zh":"门槛的定量版本","en":"The quantitative version of the threshold"},"reason":{"zh":"碰撞理论数出越过门槛的碰撞；活化能页把这道门槛记作 Eₐ，用 k = A·e^(−Eₐ/RT) 算出越过门槛的比例怎样随温度指数式增长。","en":"Collision theory counts the collisions that clear the threshold; the activation-energy lesson names the threshold Eₐ and uses k = A·e^(−Eₐ/RT) to show how the fraction clearing it grows exponentially with temperature."},"source":"../chemistry/reactions/reaction-rates/#step4"},
"collision-theory:dynamic-equilibrium":{"type":"foundation","label":{"zh":"平衡是两个速率相等","en":"Equilibrium is two equal rates"},"reason":{"zh":"知道速率是成功碰撞的次数，就能理解可逆反应：生成物越多，逆向碰撞也越多，直到正、逆两个速率相等，宏观组成不再变化。","en":"Once a rate is a count of successful collisions, reversible reactions make sense: as products build up, reverse collisions become more frequent until the forward and reverse rates match and the composition stops changing."},"source":"../chemistry/reactions/chemical-equilibrium/#step1"},
"conservation-of-mass:equation-balancing":{"type":"foundation","label":{"zh":"配平就是守恒的记账","en":"Balancing is the bookkeeping of conservation"},"reason":{"zh":"原子的种类和数目反应前后不变，所以写化学方程式时要调整系数，让每种原子在两边一样多——配平把质量守恒写进了式子。","en":"Because the kinds and numbers of atoms do not change, the coefficients of a chemical equation must make every element equal on both sides — balancing writes mass conservation into the equation."},"source":"../chemistry/reactions/mass-conservation/#step2"},
"dynamic-equilibrium:dissolution-saturation":{"type":"application","label":{"zh":"饱和是动态平衡","en":"Saturation is dynamic equilibrium"},"reason":{"zh":"饱和溶液里固体仍在溶解、溶质仍在结晶，只是两个速率相等，所以宏观上量不再变化。","en":"In a saturated solution the solid still dissolves and solute still crystallises, but at equal rates, so the amounts stop changing on the large scale."},"source":"../chemistry/solutions/dissolution-saturation/#step2"},
"dynamic-equilibrium:weak-acid-equilibrium":{"type":"foundation","label":{"zh":"酸的解离也是一种平衡","en":"Acid dissociation is one such equilibrium"},"reason":{"zh":"弱酸 HA ⇌ H⁺ + A⁻ 同样是正逆两个方向一起进行，Ka 就是这个平衡的常数；稀释、加入共同离子都是推一把平衡、看它往哪边移。","en":"A weak acid HA ⇌ H⁺ + A⁻ also runs in both directions at once, and Ka is the constant of that equilibrium; dilution and an added common ion are pushes on the balance that shift it one way or the other."},"source":"../chemistry/solutions/acid-base-equilibrium/#step0"},
"electron-shells:periodic-trends":{"type":"foundation","label":{"zh":"周期律建立在电子层上","en":"Periodic trends rest on the shell picture"},"reason":{"zh":"同一周期电子层数相同、核电荷逐个增加，同一主族最外层电子数相同——元素周期律里原子半径、电离能的走向都要从这套分层排布读起。","en":"Across a period the number of shells stays the same while the nuclear charge rises one by one, and down a group the outer-electron count repeats — the radius and ionisation-energy trends of the periodic table are read from this shell arrangement."},"source":"../chemistry/matter/atomic-structure/#step3"},
"exp-log:ph-scale":{"type":"application","label":{"zh":"对数刻度","en":"A logarithmic ruler"},"reason":{"zh":"pH 取氢离子浓度的负对数，所以刻度上差 1 对应浓度差 10 倍，差 3 对应 1000 倍。","en":"pH is the negative logarithm of the hydrogen ion concentration, so a difference of 1 on the ruler is a factor of 10 in concentration and a difference of 3 is a factor of 1000."},"source":"../chemistry/solutions/ph-scale/#step1"},
"interference:frozen-bubble":{"type":"application","label":{"zh":"彩色来自薄膜干涉","en":"The colours are thin-film interference"},"reason":{"zh":"泡壁两面反射的光走过的路程不同，按膜厚相长或相消才显出彩色；颜色随膜厚和视角改变，所以既不是冰的颜色，也不能当温度计读。","en":"Light reflected from the film’s two faces travels different paths and reinforces or cancels according to thickness, which produces the colours; since they change with thickness and viewing angle, they are neither the ice’s colour nor a thermometer."},"source":"../physics/thermal/frozen-bubble/#step2"},
"molecules-atoms:conservation-of-mass":{"type":"foundation","label":{"zh":"原子只重组，不增减","en":"Atoms regroup but never appear or vanish"},"reason":{"zh":"分子与原子页说明化学变化是拆开分子、让原子重新组合成新分子；既然原子没有增减、每个原子的质量也不变，总质量自然守恒。","en":"The molecules lesson shows a chemical change breaks molecules apart and regroups their atoms into new ones; since no atom is added or lost and each keeps its mass, the total mass must stay the same."},"source":"../chemistry/reactions/mass-conservation/#step1"},
"moromi-microbial-relay:brewed-vs-hydrolysed-soy-sauce":{"type":"foundation","label":{"zh":"省时间就是跳过接力","en":"Saving time means skipping the relay"},"reason":{"zh":"第 8 章用第 4 章的接力模型看缩短时间的办法各自跳过了哪一段：低盐固态缩短了接力，酸水解完全不用微生物。","en":"Chapter 8 uses chapter 4’s relay model to show which stage each shortcut skips: low-salt solid-state shortens the relay, and acid hydrolysis uses no microbes at all."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch8"},
"moromi-microbial-relay:soy-sauce-aroma-sources":{"type":"foundation","label":{"zh":"酵母那一段的香","en":"Aroma from the yeast stage"},"reason":{"zh":"第 6 章说酱油有而腐乳没有的香气，一处来自第 4 章酵母在盐水里的那一段。","en":"Chapter 6 traces part of the aroma that soy sauce has and sufu lacks to the yeast stage of chapter 4."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch6"},
"odour-activity-value:why-stinky-smells":{"type":"foundation","label":{"zh":"浓度除以阈值","en":"Concentration over threshold"},"reason":{"zh":"第 8 章用第 5 章的气味活度值做稀释分析：稀释之后还闻得到的，是活度值最高的那几种。","en":"Chapter 8 runs a dilution analysis on chapter 5’s odour activity values: what still smells after dilution is the few compounds with the highest values."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch8"},
"particles-states:atomic-structure":{"type":"connection","label":{"zh":"从一群粒子放大到一个原子","en":"From a crowd of particles to the inside of one atom"},"reason":{"zh":"粒子与物态讲一群粒子怎样运动、怎样排队；原子结构把其中一颗再放大，看核与电子。两页的“动”不是一回事：电子层是住址，不是跑道。","en":"Particles & states is about how a crowd of particles moves and packs; atomic structure zooms into one of them to see the nucleus and electrons. The two kinds of motion differ: an electron shell is an address, not a racetrack."},"source":"../chemistry/matter/atomic-structure/#step0"},
"particles-states:collision-theory":{"type":"foundation","label":{"zh":"温度就是粒子跑得多快","en":"Temperature is how fast the particles move"},"reason":{"zh":"粒子与物态页把温度读成粒子热运动的剧烈程度；升温让粒子跑得更快，于是碰撞更勤，也有更多碰撞的能量越过门槛。","en":"The particles lesson reads temperature as how wildly particles move; warming makes them faster, so they collide more often and more of those collisions carry enough energy to clear the threshold."},"source":"../chemistry/reactions/reaction-rates/#step2"},
"particles-states:frozen-bubble":{"type":"foundation","label":{"zh":"凝固是液体排成固体的队形","en":"Freezing is a liquid falling into a solid’s order"},"reason":{"zh":"粒子页说明固、液、气是同一群粒子的不同队形；泡壁里的水降温后排进冰的晶格，冰晶就从一粒冰核向外生长，泡里的空气仍是气体。","en":"The particles lesson shows solid, liquid and gas are one crowd of particles in different arrangements; the cooled water in the film locks into ice’s lattice and the crystal grows outward from a seed, while the air inside stays a gas."},"source":"../physics/thermal/frozen-bubble/#step0"},
"particles-states:kinetic-theory":{"type":"foundation","label":{"zh":"温度就是粒子闹腾程度的标尺","en":"Temperature gauges how wildly particles move"},"reason":{"zh":"本页温度滑杆直接调粒子抖动的剧烈程度，温度读数与粒子平均动能同源——这正是分子动理论的定性口径：越热，粒子平均动得越凶。","en":"This page's temperature slider directly sets how violently particles vibrate, and its reading shares its source with average particle kinetic energy — the qualitative statement of kinetic theory: hotter means wilder on average."},"source":"../chemistry/matter/particles-states/#step1"},
"particles-states:membrane-transport":{"type":"foundation","label":{"zh":"扩散来自分子的随机运动","en":"Diffusion comes from random molecular motion"},"reason":{"zh":"分子一直在乱动，单个分子往哪边跑都可能；只是浓度高的一侧分子更多，统计上穿过去的更多，净通量才顺着浓度差。","en":"Molecules are always jostling, and any single one may go either way; there are simply more on the crowded side, so statistically more cross from there, and the net flux runs down the gradient."},"source":"../biology/cells/membrane-transport/"},
"particles-states:molecules-atoms":{"type":"representation","label":{"zh":"粒子是分子原子的教学化身","en":"Particles are the teaching stand-in for molecules and atoms"},"reason":{"zh":"固液气不是三种东西，是同一群粒子排出的三种队形；粒子页画的圆盘，就是分子原子尺度的放大图。","en":"Solid, liquid and gas are not three things but three formations of the same particles; the discs this page draws are the magnified picture of the molecular and atomic scale."},"source":"../chemistry/matter/particles-states/#step0"},
"particles-states:water-cycle":{"type":"application","label":{"zh":"蒸发与沸腾是水循环里的两条进气路","en":"Evaporation and boiling are water's two routes into gas"},"reason":{"zh":"一杯水变干是表面少数粒子逃逸，烧开是全体挣脱成气；水循环追踪的正是同一批水在这两条路与液化之间跑。","en":"A cup drying out is a few surface particles escaping; boiling is everyone breaking free. The water cycle tracks the same water running between these two routes and liquefaction."},"source":"../chemistry/matter/particles-states/#step3"},
"ph-scale:weak-acid-equilibrium":{"type":"foundation","label":{"zh":"pH 读的是平衡时的 H⁺","en":"pH reads the H⁺ left at equilibrium"},"reason":{"zh":"pH 标度把 [H⁺] 取负对数；弱酸只放出一部分 H⁺，所以同浓度的弱酸 pH 比强酸高，要先由 Ka 算出平衡时的 [H⁺] 才能读 pH。","en":"The pH scale is −log of [H⁺]; a weak acid releases only part of its H⁺, so at the same concentration its pH is higher than a strong acid’s, and [H⁺] must first be found from Ka."},"source":"../chemistry/solutions/acid-base-equilibrium/#step1"},
"protein-hydrolysis-taste:endo-exo-peptidase":{"type":"foundation","label":{"zh":"谁来切、怎么切","en":"Who cuts, and how"},"reason":{"zh":"第 2 章接着第 1 章的随机断链往下问：从链中间切的内切酶和从链端一个个剪的外切酶各自很慢，合在一起才快。","en":"Chapter 2 takes chapter 1’s random chain scission further: an enzyme that cuts mid-chain and one that trims the ends are each slow alone, and fast only together."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch2"},
"protein-hydrolysis-taste:umami-synergy":{"type":"foundation","label":{"zh":"切下来的谷氨酸","en":"The glutamate set free"},"reason":{"zh":"第 3 章讲的鲜味来自游离谷氨酸；第 1 章说明了为什么它只有从蛋白质链上切下来之后才尝得到。","en":"Chapter 3’s umami comes from free glutamate; chapter 1 shows why it can be tasted only once it is cut from the protein chain."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch3"},
"soy-sauce-browning:soy-sauce-aroma-sources":{"type":"foundation","label":{"zh":"加热也出香","en":"Heating makes aroma too"},"reason":{"zh":"第 6 章的另一处香气来自压榨后的加热，和第 5 章让颜色变深的是同一类反应。","en":"The other source of aroma in chapter 6 is the heating after pressing, the same family of reactions that darkens the colour in chapter 5."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch6"},
"soybean-wheat-ratio:moromi-microbial-relay":{"type":"foundation","label":{"zh":"小麦的糖喂后面的菌","en":"Wheat sugar feeds what comes next"},"reason":{"zh":"第 4 章的乳酸菌和酵母吃的是第 3 章小麦淀粉变成的糖；不加小麦，接力的后半段就没有多少原料。","en":"The lactic bacteria and yeast of chapter 4 live on the sugar that chapter 3’s wheat starch becomes; without wheat the second half of the relay has little to work on."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch4"},
"soybean-wheat-ratio:soy-sauce-browning":{"type":"foundation","label":{"zh":"糖是变色的一半","en":"Sugar is half of the browning"},"reason":{"zh":"第 5 章的美拉德反应需要氨基酸和糖两样东西，糖来自第 3 章的小麦。","en":"The Maillard reaction of chapter 5 needs both amino acids and sugars, and the sugars come from chapter 3’s wheat."},"source":"../food/flavor/how-soy-sauce-gets-its-flavor/#ch5"},
"umami-synergy:fermented-food-family":{"type":"foundation","label":{"zh":"同一把尺子","en":"The same yardstick"},"reason":{"zh":"第 7 章沿用第 3 章的味觉阈值，把腐乳和松花蛋黄里的鲜味物质放在同一把尺子上比。","en":"Chapter 7 reuses chapter 3’s taste thresholds to put the umami compounds of sufu and century-egg yolk on one scale."},"source":"../food/flavor/why-fermented-tofu-tastes-good/#ch7"},
"weak-acid-equilibrium:buffer-solution":{"type":"foundation","label":{"zh":"Ka 与共同离子是缓冲的地基","en":"Ka and the common ion underlie buffering"},"reason":{"zh":"缓冲液里同时有大量 HA 和 A⁻：pKa 定下它在哪个 pH 附近最稳，共同离子效应解释了为什么此时 pH 只看两者的比值。","en":"A buffer holds plenty of both HA and A⁻: pKa sets the pH it holds best, and the common-ion effect explains why the pH then depends only on their ratio."},"source":"../chemistry/solutions/buffer-capacity/#step1"}
}});
